const findStoresByFilter = `-- name: FindStoresByFilter :many
SELECT
    s.id,
    s.name,
    s.score,
    s.is_open,
    s.type,
    s.delivery_time,
    s.neighborhood,
    s.latitude,
    s.longitude,
    s.profile_image,
    COUNT(*) OVER () AS total_items
FROM store s
WHERE 1 = 1
  AND (
    NULLIF($1::text, '') IS NULL
        OR unaccent(s.name) ILIKE '%' || unaccent($1::text) || '%'
    )
  AND (
    NULLIF($2::text, '') IS NULL
        OR s.type::text = $2
    )
  AND (
    NULLIF($3::text, '') IS NULL
        OR s.city = $3
    )
  AND (
      NULLIF($4::integer, 0) = 0
        or s.score >= $4
    )
  AND (
    $5::boolean IS NULL
        OR s.is_open = $5::boolean
    )
ORDER BY s.score DESC, s.type
OFFSET $6
    LIMIT $7
`

