//	    s.is_open,
//	    s.type,
//	    s.delivery_time,
//	    s.neighborhood,
//	    s.latitude,
//	    s.longitude,
//	    s.profile_image,
//	    COUNT(*) OVER () AS total_items
//	FROM store s
//	WHERE 1 = 1
//	  AND (
//	    NULLIF($1::text, '') IS NULL
//	        OR unaccent(s.name) ILIKE '%' || unaccent($1::text) || '%'
//	    )
//	  AND (
//	    NULLIF($2::text, '') IS NULL
//	        OR s.type::text = $2
//	    )
//	  AND (
//	    NULLIF($3::text, '') IS NULL
//	        OR s.city = $3
//	    )
//	  AND (
//	      NULLIF($4::integer, 0) = 0
//	        or s.score >= $4
//	    )
//	  AND (
//	    $5::boolean IS NULL
//	        OR s.is_open = $5::boolean
//	    )
//	ORDER BY s.score DESC, s.type
//	OFFSET $6
//	    LIMIT $7
func (q *Queries) FindStoresByFilter(ctx context.Context, arg FindStoresByFilterParams) ([]FindStoresByFilterRow, error) {
	rows, err := q.db.Query(ctx, findStoresByFilter,
		arg.Name,
		arg.Type,
		arg.City,
		arg.Score,
		arg.IsOpen,
		arg.OffsetValue,
		arg.LimitItems,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []FindStoresByFilterRow
	for rows.Next() {
		var i FindStoresByFilterRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.Score,
			&i.IsOpen,
			&i.Type,
			&i.DeliveryTime,
			&i.Neighborhood,
			&i.Latitude,
			&i.Longitude,
			&i.ProfileImage,
			&i.TotalItems,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

